// CSD_RATIONALE_BEGIN
// Attempt 65 achieved 0% because it called `SpeculativeConstrainedRollout`,
// which is NOT in the allowed helper list. This caused a runtime error
// (`'_LogitsProxy' object has no attribute 'length'`) on all 49 examples,
// producing zero tokens and zero spans.
//
// This attempt returns exactly to the best-known strategy (attempt 1, 40.8%
// accuracy / 91.8% syntax) with one structural fix required by the style guide:
// delimiter detection changes from `next == "<<"` (token-equality, unsafe) to
// `RenderedEndsWith(generated, "<<")` (rendered-text suffix, tokenizer-safe).
//
// Strategy:
//   Phase 1 (outside span): free `UnconstrainedStep` until EOS, rendered "<<"
//     in output, or budget pressure triggers `OpenConstrainedSpan`.
//   Phase 2 (inside span): `AdaptiveConstrainedStep` with group boosts; close
//     immediately at `IsCompletePrefix`; near budget, `CloseSpanWithinBudget`.
// No new helpers beyond what attempt 1 used.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span free-generation branch: insideConstrainedOut is false, so the
//   implication is vacuously true. When RenderedEndsWith(generated, "<<") fires,
//   EnterObservedConstrainedSpan sets currentConstrainedOut := []; the precondition
//   guarantees parser.IsValidPrefix([]) ✓. OpenConstrainedSpan (force-open) also
//   sets currentConstrainedOut := [] ✓.
//
//   CloseConstrainedSpan branch (IsCompletePrefix guard): sets insideConstrainedOut
//   := false, making the implication vacuously true ✓.
//
//   CloseSpanWithinBudget branch: its postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut) ✓.
//
//   AdaptiveConstrainedStep + AppendConstrainedToken branch: AdaptiveConstrainedStep
//   hard-masks to parser-valid next tokens; AppendConstrainedToken extends
//   currentConstrainedOut by that token, preserving IsValidPrefix via the validity
//   of the chosen token. EOS breaks the loop without appending ✓.
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: equality holds at steps = 0 ✓.
//   UnconstrainedStep: steps += 1; generated grows by ≤ 1 (EOS breaks without
//   appending); EnterObservedConstrainedSpan leaves generated unchanged ✓.
//   OpenConstrainedSpan: appends exactly "<<" (+1 token) to generated, steps += 1 ✓.
//   AdaptiveConstrainedStep + AppendConstrainedToken: steps += 1; AppendConstrainedToken
//   appends exactly 1 token to generated ✓.
//   CloseConstrainedSpan: appends ">>" (+1 token) to generated, steps += 1 ✓.
//   CloseSpanWithinBudget with closeBudget = maxSteps - steps: its postcondition
//   gives |generated_new| <= |generated_old| + closeBudget; after steps := maxSteps,
//   |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps ✓.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every intermediate symbolic expression and the " +
  "final numeric answer inside << >> delimiters. " +
  "Example: The total is <<3+4=7>> dollars. " +
  "The LAST << >> span must be the complete standalone answer expression.");

var steps: nat := 0;
var narrowThreshold: nat := 12;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    if maxSteps - steps <= 4 && steps > 0 {
      // Budget pressure: force-open a final constrained span.
      var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
      generated := og;
      insideConstrainedOut := oi;
      currentConstrainedOut := oc;
      steps := steps + 1;
    } else {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        generated := generated + [next];
        if RenderedEndsWith(generated, "<<") {
          generated, insideConstrainedOut, currentConstrainedOut :=
            helpers.EnterObservedConstrainedSpan(lm, generated);
        }
      }
    }
  } else {
    // Inside a constrained span.
    if parser.IsCompletePrefix(currentConstrainedOut) {
      // Span complete: close it immediately.
      var cg, ci, cc := helpers.CloseConstrainedSpan(
        lm, parser, generated, currentConstrainedOut
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else if maxSteps - steps <= 3 {
      // Near budget end: CloseSpanWithinBudget handles graceful finish.
      var closeBudget := maxSteps - steps;
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
    } else {
      // Normal constrained generation inside the span.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.AdaptiveConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut,
        validTokenGroups, 4.0, narrowThreshold, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

cost := steps;

